package com.bank.youngest;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class YoungestDemo {
    private static final Logger log = Logger.getLogger("Youngest");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", Gender.MALE, 34),
            new Employee("Amit", Gender.MALE, 28),
            new Employee("Priya", Gender.FEMALE, 41),
            new Employee("Neha", Gender.FEMALE, 30));
        YoungestService service = new YoungestService();

        Map<Gender, Optional<Employee>> youngest = service.youngestByGender(staff);
        youngest.forEach((g, opt) -> log.info(() -> g + " → "
            + opt.map(Employee::getName).orElse("none")));
    }
}

// ─── Would be in model/Gender.java ───
enum Gender { MALE, FEMALE }

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final Gender gender;
    private final int age;
    Employee(String name, Gender gender, int age) {
        this.name = name; this.gender = gender; this.age = age;
    }
    String getName() { return name; }
    Gender getGender() { return gender; }
    int getAge() { return age; }
}

// ─── Would be in service/YoungestService.java ───
class YoungestService {
    Map<Gender, Optional<Employee>> youngestByGender(List<Employee> staff) {
        return staff.stream()
            .filter(e -> e.getGender() != null)
            .collect(groupingBy(
                Employee::getGender,
                minBy(Comparator.comparingInt(Employee::getAge))   // youngest per group
                    ));
    }
}
